class MegatronTrainRayActor(TrainRayActor):
    @with_defer(lambda: Timer().start("train_wait"))
    def init(
        self,
        args: Namespace,
        role: str,
        with_ref: bool = False,
    ) -> int | None:
        monkey_patch_torch_dist()
        _install_process_group_compat()

        super().init(args, role, with_ref)

        init(args)

        if args.dumper_enable:
            from sglang.srt.debug_utils.dumper import dumper

            dumper.apply_source_patches()

        self._is_main_rank = is_megatron_main_rank()

        if self._is_main_rank:
            init_tracking(args, primary=False)

        unsupported = {"train_actor", "train_log_probs"} & set(args.profile_target)
        if unsupported and args.use_pytorch_profiler:
            raise NotImplementedError(
                f"--profile-target {' '.join(sorted(unsupported))} is not supported for Megatron backend"
            )
        self.prof = TrainProfiler(args)

        # read config and tokenizer serialized to prevent concurrent writing bug.
        for i in range(dist.get_world_size()):
            if i == dist.get_rank():
                self.hf_config = AutoConfig.from_pretrained(args.hf_checkpoint, trust_remote_code=True)
                self.tokenizer = load_tokenizer(
                    self.args.hf_checkpoint, chat_template_path=self.args.chat_template_path, trust_remote_code=True
                )
            dist.barrier(group=get_gloo_group())

        self.train_parallel_config = {
            "dp_size": get_parallel_state().intra_dp.size,
        }
        dist.barrier(group=get_gloo_group())

        if args.offload_train:
            if (x := args.train_memory_margin_bytes) > 0:
                # --train-memory-margin-bytes can tune this
                logger.info(f"Set torch_memory_saver.memory_margin_bytes to {x}")
                torch_memory_saver.memory_margin_bytes = x

        if self.args.debug_rollout_only:
            return 0

        if role == "critic":
            self.args.load = self.args.critic_load
            self.args.save = self.args.critic_save
            self.args.lr = self.args.critic_lr
            self.args.lr_warmup_iters = self.args.critic_lr_warmup_iters
            self.args.disable_param_buffers_cpu_backup = False
        else:
            for m in all_replay_managers:
                m.enabled = getattr(self.args, f"use_{m.name}_replay")
                m.enable_check_replay_result = m.enabled and self.args.ci_test

        (self.model, self.optimizer, self.opt_param_scheduler, loaded_rollout_id) = initialize_model_and_optimizer(
            args, role
        )

        parallel_state = get_parallel_state()
        if parallel_state.cp.size > 1:
            from miles_plugins.models.cp_utils import detect_and_setup_hybrid_cp

            for model_chunk in self.model:
                detect_and_setup_hybrid_cp(
                    model_chunk, parallel_state.cp.group, parallel_state.cp.rank, parallel_state.cp.size
                )

        verify_megatron_parallel_state(self.model)

        if role == "critic":
            if self.args.offload_train:
                self.sleep()
            return

        start_rollout_id = loaded_rollout_id + 1

        self.weights_backuper = TensorBackuper.create(
            source_getter=lambda: named_params_and_buffers(
                self.args,
                self.model,
                convert_to_global_name=args.megatron_to_hf_mode == "raw",
                translate_gpu_to_cpu=not self.args.enable_weights_backuper,
            ),
            single_tag=None if args.enable_weights_backuper else "actor",
        )
        self._active_model_tag: str | None = "actor"
        self.weights_backuper.backup("actor")

        if with_ref:
            self.load_other_checkpoint("ref", args.ref_load)

        if self.args.keep_old_actor:
            # Load old_actor checkpoint
            self.load_other_checkpoint("old_actor", args.load)
            # Create rollout_actor as a copy of current actor
            if args.update_weights_interval == 1:
                self.weights_backuper.backup("rollout_actor")

        if self.args.vocab_size is None:
            self.args.vocab_size = self.tokenizer.vocab_size

        if self.args.colocate:
            update_weight_cls = UpdateWeightFromTensor
        else:
            if self.args.update_weight_transfer_mode == "broadcast":
                update_weight_cls = UpdateWeightFromDistributed
            else:

            rewards = rewards.reshape(-1, self.args.n_samples_per_prompt)
        else:
            # when samples count are not equal in each group
            rewards = rewards.view(-1, rewards.shape[-1])
        mean = rewards.mean(dim=-1, keepdim=True)
        rewards = rewards - mean

        if self.args.advantage_estimator in ["grpo", "gspo"] and self.args.grpo_std_normalization:
            std = rewards.std(dim=-1, keepdim=True)
            rewards = rewards / (std + 1e-6)

        return raw_rewards, rewards.flatten().tolist()

    return raw_rewards, shaped_rewards

def _convert_samples_to_train_data(self, samples: list[Sample] | list[list[Sample]]):
    """
    Convert inference generated samples to training data.
    """
    if self.custom_convert_samples_to_train_data_func is not None:
        return self.custom_convert_samples_to_train_data_func(self.args, samples)

    raw_rewards, rewards = self._post_process_rewards(samples)

    assert len(raw_rewards) == len(samples)
    assert len(rewards) == len(samples)

    # --critic-exclude-overlong-penalty: ship a second per-sample reward without the soft
    # overlong punishment for the critic's regression target. The penalty is additive, so
    # subtracting it from the shaped reward is exact. Absent the flag this branch adds
    # nothing and the batch is unchanged.
    critic_rewards = None
    if getattr(self.args, "critic_exclude_overlong_penalty", False):
        if (
            self.custom_reward_post_process_func is None
            and getattr(self.args, "overlong_buffer_len", 0)
            and all(isinstance(r, (int, float)) for r in raw_rewards)
        ):
            critic_rewards = [
                r - compute_overlong_penalty(self.args, sample.response_length)
                for r, sample in zip(rewards, samples, strict=True)
            ]
        else:
            logger.warning(
                "critic_exclude_overlong_penalty is set but no overlong penalty was applied "
                "(custom reward post-process, non-scalar rewards, or overlong_buffer_len=0); "
                "critic rewards fall back to the shaped rewards."
            )
            critic_rewards = list(rewards)

    train_data = {
        "tokens": [sample.tokens for sample in samples],
        "response_lengths": [sample.response_length for sample in samples],
        # some reward model, e.g. remote rm, may return multiple rewards,
        # we could use key to select the reward.
        "rewards": rewards,
        "raw_reward": raw_rewards,
        "truncated": [1 if sample.status == Sample.Status.TRUNCATED else 0 for sample in samples],
        "sample_indices": [sample.index for sample in samples],
    }
    if critic_rewards is not None:
        train_data["critic_rewards"] = critic_rewards

    # loss mask
    # TODO: compress the loss mask
    loss_masks = []
    for sample in samples:
        # always instantiate loss_mask if not provided
        if sample.loss_mask is None:
            sample.loss_mask = [1] * sample.response_length

        assert (
            len(sample.loss_mask) == sample.response_length
        ), f"loss mask length {len(sample.loss_mask)} != response length {sample.response_length}"
        if sample.remove_sample or sample.metadata.get("env_error"):
            sample.loss_mask = [0] * sample.response_length
        # DAPO Overlong Filtering: drop truncated (length-capped) samples from the gradient.
        if getattr(self.args, "overlong_filtering", False) and sample.status == Sample.Status.TRUNCATED:
            sample.loss_mask = [0] * sample.response_length
        loss_masks.append(sample.loss_mask)
    train_data["loss_masks"] = loss_masks

    # overwriting the raw reward
    if samples[0].metadata and "raw_reward" in samples[0].metadata:
        train_data["raw_reward"] = [sample.metadata["raw_reward"] for sample in samples]

    if any(sample.metadata.get("env_error") for sample in samples):
        train_data["env_error"] = [1 if sample.metadata.get("env_error") else 0 for sample in samples]

    # For rollout buffer
    if samples[0].metadata and "round_number" in samples[0].metadata:
        train_data["round_number"] = [sample.metadata["round_number"] for sample in samples]

    # Add rollout log probabilities for off-policy correction
    if samples[0].rollout_log_probs is not None:
        train_data["rollout_log_probs"] = [sample.rollout_log_probs for sample in samples]

    if samples[0].rollout_routed_experts is not None:
        train_data["rollout_routed_experts"] = [sample.rollout_routed_experts for sample in samples]

    if getattr(samples[0], "rollout_routed_experts_weights", None) is not None:
        train_data["rollout_routed_experts_weights"] = [
            getattr(sample, "rollout_routed_experts_weights", None) for sample in samples
        ]

    if samples[0].train_metadata is not None:
        train_data["metadata"] = [sample.train_metadata for sample in samples]

    if any(sample.multimodal_train_inputs is not None for sample in samples):
        train_data["multimodal_train_inputs"] = [sample.multimodal_train_inputs for sample in samples]

    if any(sample.weight_versions for sample in samples):
        train_data["weight_versions"] = [sample.weight_versions for sample in samples]

    if "teacher_log_probs" in samples[0].__dict__:
        train_data["teacher_log_probs"] = [sample.teacher_log_probs for sample in samples]

    # Pass dynamic global_batch_size to training side
    assert self.args.use_dynamic_global_batch_size == hasattr(self, "_dynamic_global_batch_size")
    if hasattr(self, "_dynamic_global_batch_size"):

"""Chunked moment accumulator for distributed masked whitening."""
from functools import reduce
from operator import add

import torch


class MomentReducer:
    """Accumulate masked first and second moments in fixed-width chunks."""

    def __init__(self, width: int = 4096):
        self.width = width
        self._origins: dict[tuple[torch.device, torch.dtype], torch.Tensor] = {}

    def __call__(self, values: torch.Tensor, mask: torch.Tensor) -> torch.Tensor:
        key = (values.device, torch.float32)
        origin = self._origins.get(key)
        if origin is None:
            origin = torch.zeros(2, device=values.device, dtype=torch.float32)
            self._origins[key] = origin
        blocks = (
            torch.stack(((x * m).sum(), (x.square() * m).sum())).float()
            for start in range(0, values.numel(), self.width)
            for x, m in [(values[start : start + self.width], mask[start : start + self.width])]
        )
        return reduce(add, blocks, origin)

